var __DC_CHILDREN={"Header":{"h":"\n<helmet>\n<link href=\"https://fonts.googleapis.com/css2?family=Inter:wght@400;500;600;700&display=swap\" rel=\"stylesheet\">\n<link href=\"https://cdn.jsdelivr.net/npm/remixicon@4.5.0/fonts/remixicon.css\" rel=\"stylesheet\">\n<style>\n  :root{--primary:#4D42E9;--primary-darker:#312D86;--primary-lighter:#EEF2FF;--n100:#F6F8FA;--n200:#E2E4E9;--n400:#868C98;--n500:#525866;--n600:#31353F;--n900:#0A0D14;--stroke:#E2E4E9;}\n  @keyframes hdr-drop{from{opacity:0;transform:translateY(-6px)}to{opacity:1;transform:none}}\n</style>\n</helmet>\n<header style=\"background:#fff;border-bottom:1px solid var(--stroke);font-family:'Inter',sans-serif;\">\n  <div style=\"max-width:1440px;margin:0 auto;padding:12px 40px;display:flex;align-items:center;gap:24px;\">\n    <a href=\"Портал Минздрава - Главная.dc.html\" style=\"display:flex;align-items:center;gap:12px;text-decoration:none;flex:0 0 auto;\">\n      <img src=\"data:image/jpeg;base64,\" alt=\"Герб Республики Казахстан\" style=\"width:48px;height:48px;object-fit:contain;flex:0 0 auto;\" />\n      <div style=\"line-height:1.2;max-width:240px;\">\n        <div style=\"font-size:14px;font-weight:600;color:var(--n900);letter-spacing:-.01em;\">Министерство здравоохранения</div>\n        <div style=\"font-size:12px;color:var(--n400);font-weight:500;\">Республики Казахстан</div>\n      </div>\n    </a>\n\n    <sc-if value=\"{{ showRoles }}\" hint-placeholder-val=\"{{ true }}\">\n      <nav style=\"display:flex;align-items:stretch;gap:4px;flex:0 0 auto;align-self:stretch;margin-left:8px;\">\n        <sc-for list=\"{{ roles }}\" as=\"r\" hint-placeholder-count=\"3\">\n          <button onClick=\"{{ r.onClick }}\" style=\"{{ r.style }}\">\n            <span style=\"display:flex;align-items:center;gap:8px;\"><i class=\"{{ r.icon }}\" style=\"font-size:18px;\"></i>{{ r.label }}</span>\n            <span style=\"{{ r.underline }}\"></span>\n          </button>\n        </sc-for>\n      </nav>\n    </sc-if>\n\n    <div style=\"flex:1;\"></div>\n\n    <div style=\"display:flex;align-items:center;gap:10px;flex:0 0 auto;\">\n      <div style=\"position:relative;\">\n        <button onClick=\"{{ toggleLang }}\" style=\"display:flex;align-items:center;gap:8px;height:40px;padding:0 12px 0 14px;border:1px solid var(--stroke);border-radius:10px;background:#fff;font-family:inherit;font-size:14px;font-weight:600;color:var(--n600);cursor:pointer;\">\n          <i class=\"ri-global-line\" style=\"font-size:18px;color:var(--n400);\"></i>{{ currentLang }}<i class=\"{{ chevron }}\" style=\"font-size:18px;color:var(--n400);\"></i>\n        </button>\n        <sc-if value=\"{{ langOpen }}\" hint-placeholder-val=\"{{ false }}\">\n          <div onClick=\"{{ closeLang }}\" style=\"position:fixed;inset:0;z-index:44;\"></div>\n          <div style=\"position:absolute;right:0;top:calc(100% + 6px);z-index:45;background:#fff;border:1px solid var(--stroke);border-radius:12px;padding:6px;min-width:160px;box-shadow:0 12px 24px -8px rgba(10,13,20,.16);animation:hdr-drop .15s ease;\">\n            <sc-for list=\"{{ langs }}\" as=\"l\" hint-placeholder-count=\"3\">\n              <button onClick=\"{{ l.onClick }}\" style=\"{{ l.style }}\"><span>{{ l.name }}</span><i class=\"{{ l.check }}\" style=\"font-size:18px;color:var(--primary);\"></i></button>\n            </sc-for>\n          </div>\n        </sc-if>\n      </div>\n      <sc-if value=\"{{ showLogin }}\" hint-placeholder-val=\"{{ true }}\">\n        <a href=\"Вход.dc.html\" style=\"height:40px;padding:0 18px;border-radius:10px;background:var(--primary);color:#fff;font-size:14px;font-weight:500;font-family:inherit;cursor:pointer;display:flex;align-items:center;gap:8px;box-shadow:0 1px 2px rgba(10,13,20,.04);text-decoration:none;\">\n          <i class=\"ri-shield-user-line\" style=\"font-size:18px;\"></i>Войти\n        </a>\n      </sc-if>\n      <sc-if value=\"{{ isAccount }}\" hint-placeholder-val=\"{{ false }}\">\n        <a href=\"Портал Минздрава - Главная.dc.html\" style=\"height:40px;padding:0 16px;border:1px solid var(--stroke);border-radius:10px;background:#fff;color:var(--n600);font-size:14px;font-weight:500;font-family:inherit;cursor:pointer;display:flex;align-items:center;gap:8px;text-decoration:none;\">\n          <i class=\"ri-home-4-line\" style=\"font-size:18px;\"></i>На главную\n        </a>\n      </sc-if>\n    </div>\n  </div>\n</header>\n","j":"\nclass Component extends DCLogic {\n  state = { lang:'РУС', role:'citizens', langOpen:false };\n  componentDidMount(){\n    try { const r = localStorage.getItem('mp-role'); if(r) this.setState({ role:r }); } catch(e){}\n    try { const l = localStorage.getItem('mp-lang'); if(l) this.setState({ lang:l }); } catch(e){}\n    this._onRole = (e) => { if(e && e.detail) this.setState({ role:e.detail }); };\n    window.addEventListener('mp-role-change', this._onRole);\n  }\n  componentWillUnmount(){ window.removeEventListener('mp-role-change', this._onRole); }\n  setRole(id){\n    this.setState({ role:id });\n    try { localStorage.setItem('mp-role', id); } catch(e){}\n    try { window.dispatchEvent(new CustomEvent('mp-role-change', { detail:id })); } catch(e){}\n  }\n  setLang(code){\n    this.setState({ lang:code, langOpen:false });\n    try { localStorage.setItem('mp-lang', code); } catch(e){}\n  }\n  renderVals(){\n    const s = this.state;\n    const roleData = [\n      { id:'citizens', label:'Гражданам', icon:'ri-user-3-line' },\n      { id:'business', label:'Бизнесу', icon:'ri-briefcase-4-line' },\n      { id:'medical', label:'Медперсоналу', icon:'ri-stethoscope-line' },\n    ];\n    const roles = roleData.map(r => { const on = s.role===r.id; return { ...r, onClick:()=>this.setRole(r.id),\n      style:`position:relative;display:flex;flex-direction:column;align-items:center;justify-content:center;padding:0 16px;height:46px;border:none;background:none;font-family:inherit;font-size:14px;font-weight:${on?'600':'500'};cursor:pointer;transition:color .15s;white-space:nowrap;color:${on?'#4D42E9':'#525866'};`,\n      underline:`position:absolute;left:6px;right:6px;bottom:-1px;height:2.5px;border-radius:2px;background:${on?'#4D42E9':'transparent'};transition:.15s;` }; });\n\n    const langData = [ { code:'ҚАЗ', name:'Қазақша' }, { code:'РУС', name:'Русский' }, { code:'ENG', name:'English' } ];\n    const langs = langData.map(l => ({ ...l, onClick:()=>this.setLang(l.code), check: s.lang===l.code ? 'ri-check-line' : 'ri-checkbox-blank-line',\n      style:`width:100%;display:flex;align-items:center;justify-content:space-between;gap:12px;padding:9px 12px;border:none;border-radius:8px;font-family:inherit;font-size:14px;font-weight:${s.lang===l.code?'600':'500'};text-align:left;cursor:pointer;background:${s.lang===l.code?'#EEF2FF':'transparent'};color:${s.lang===l.code?'#312D86':'#31353F'};` }));\n    const langs2 = langs.map(l => ({ ...l, check: s.lang===l.code ? 'ri-check-line' : '' }));\n\n    const isAccount = this.props.variant === 'account';\n    return {\n      roles,\n      showRoles: !isAccount,\n      showLogin: !isAccount,\n      isAccount,\n      currentLang: s.lang,\n      langOpen: s.langOpen,\n      chevron: s.langOpen ? 'ri-arrow-up-s-line' : 'ri-arrow-down-s-line',\n      toggleLang: ()=>this.setState(st=>({ langOpen:!st.langOpen })),\n      closeLang: ()=>this.setState({ langOpen:false }),\n      langs: langs2,\n    };\n  }\n}\n"},"Footer":{"h":"\n<helmet>\n<link href=\"https://fonts.googleapis.com/css2?family=Inter:wght@400;500;600;700&display=swap\" rel=\"stylesheet\">\n<link href=\"https://cdn.jsdelivr.net/npm/remixicon@4.5.0/fonts/remixicon.css\" rel=\"stylesheet\">\n<style>:root{--primary:#4D42E9;--primary-darker:#312D86;--n900:#0A0D14;}</style>\n</helmet>\n<footer style=\"background:var(--n900);color:rgba(255,255,255,.7);font-family:'Inter',sans-serif;\">\n  <div style=\"max-width:1440px;margin:0 auto;padding:56px 40px 32px;\">\n    <div style=\"display:grid;grid-template-columns:1.4fr 1fr 1fr 1fr;gap:40px;\">\n      <div>\n        <div style=\"display:flex;align-items:center;gap:12px;margin-bottom:18px;\">\n          <div style=\"width:42px;height:42px;border-radius:12px;background:linear-gradient(135deg,var(--primary),var(--primary-darker));display:flex;align-items:center;justify-content:center;\"><i class=\"ri-heart-pulse-fill\" style=\"color:#fff;font-size:22px;\"></i></div>\n          <div style=\"line-height:1.2;color:#fff;\"><div style=\"font-size:14px;font-weight:600;\">Министерство здравоохранения</div><div style=\"font-size:12px;color:rgba(255,255,255,.5);\">Республики Казахстан</div></div>\n        </div>\n        <p style=\"font-size:13px;line-height:1.6;color:rgba(255,255,255,.55);max-width:320px;margin:0 0 18px;\">Единая цифровая платформа здравоохранения. Услуги, информация и электронные сервисы — в одном месте.</p>\n        <div style=\"display:flex;gap:10px;\">\n          <sc-for list=\"{{ socials }}\" as=\"s\" hint-placeholder-count=\"4\">\n            <div style=\"width:38px;height:38px;border-radius:10px;background:rgba(255,255,255,.08);display:flex;align-items:center;justify-content:center;cursor:pointer;\"><i class=\"{{ s }}\" style=\"font-size:18px;color:#fff;\"></i></div>\n          </sc-for>\n        </div>\n      </div>\n      <div>\n        <div style=\"font-size:12px;font-weight:600;letter-spacing:.06em;text-transform:uppercase;color:#fff;margin-bottom:16px;\">О портале</div>\n        <div style=\"display:flex;flex-direction:column;gap:11px;\">\n          <sc-for list=\"{{ about }}\" as=\"l\" hint-placeholder-count=\"7\"><a href=\"#\" style=\"font-size:13px;color:rgba(255,255,255,.6);text-decoration:none;\">{{ l }}</a></sc-for>\n        </div>\n      </div>\n      <div>\n        <div style=\"font-size:12px;font-weight:600;letter-spacing:.06em;text-transform:uppercase;color:#fff;margin-bottom:16px;\">Популярные разделы</div>\n        <div style=\"display:flex;flex-direction:column;gap:11px;\">\n          <sc-for list=\"{{ popular }}\" as=\"l\" hint-placeholder-count=\"6\"><a href=\"{{ l.href }}\" style=\"font-size:13px;color:rgba(255,255,255,.6);text-decoration:none;\">{{ l.label }}</a></sc-for>\n        </div>\n      </div>\n      <div>\n        <div style=\"font-size:12px;font-weight:600;letter-spacing:.06em;text-transform:uppercase;color:#fff;margin-bottom:16px;\">Контакты</div>\n        <div style=\"display:flex;flex-direction:column;gap:11px;\">\n          <sc-for list=\"{{ contacts }}\" as=\"c\" hint-placeholder-count=\"4\">\n            <div style=\"display:flex;align-items:center;gap:10px;font-size:13px;color:rgba(255,255,255,.6);\"><i class=\"{{ c.icon }}\" style=\"font-size:16px;color:rgba(255,255,255,.4);\"></i>{{ c.text }}</div>\n          </sc-for>\n        </div>\n      </div>\n    </div>\n    <div style=\"border-top:1px solid rgba(255,255,255,.1);margin-top:40px;padding-top:24px;display:flex;align-items:center;justify-content:space-between;flex-wrap:wrap;gap:12px;\">\n      <span style=\"font-size:13px;color:rgba(255,255,255,.5);\">© Министерство здравоохранения Республики Казахстан</span>\n      <span style=\"font-size:13px;color:rgba(255,255,255,.4);\">Версия портала 1.0 · Обновлено 24.06.2026</span>\n    </div>\n  </div>\n</footer>\n","j":"\nclass Component extends DCLogic {\n  renderVals(){\n    return {\n      socials: ['ri-facebook-fill','ri-instagram-line','ri-youtube-fill','ri-telegram-fill'],\n      about: ['О портале','О Министерстве здравоохранения','Новости','Телемедицина','Частые вопросы','Пользовательское соглашение','Политика конфиденциальности'],\n      popular: [\n        { label:'Каталог медицинских услуг', href:'Каталог услуг.dc.html' },\n        { label:'Медицинские организации', href:'Медорганизации.dc.html' },\n        { label:'Лекарства', href:'Лекарства.dc.html' },\n        { label:'Проверка ОСМС', href:'ОСМС.dc.html' },\n        { label:'Справочник заболеваний', href:'Заболевания.dc.html' },\n        { label:'Вакцинация', href:'Вакцинация.dc.html' },\n      ],\n      contacts: [\n        { icon:'ri-phone-line', text:'1414 — служба поддержки' },\n        { icon:'ri-mail-line', text:'support@dsm.gov.kz' },\n        { icon:'ri-map-pin-line', text:'г. Астана, проспект Мәңгілік Ел, 8' },\n        { icon:'ri-time-line', text:'Круглосуточно, без выходных' },\n      ],\n    };\n  }\n}\n"},"Assistant":{"h":"\n<helmet>\n<link href=\"https://fonts.googleapis.com/css2?family=Inter:wght@400;500;600;700&display=swap\" rel=\"stylesheet\">\n<link href=\"https://cdn.jsdelivr.net/npm/remixicon@4.5.0/fonts/remixicon.css\" rel=\"stylesheet\">\n<style>\n  :root{--primary:#4D42E9;--primary-darker:#312D86;--green:#38C793;--n100:#F6F8FA;--n400:#868C98;--n500:#525866;--n700:#20232D;--n900:#0A0D14;--stroke:#E2E4E9;}\n  @keyframes mp-fade{from{opacity:0}to{opacity:1}}\n  @keyframes mp-pop{from{opacity:0;transform:translateY(12px) scale(.98)}to{opacity:1;transform:none}}\n  .mp-scroll::-webkit-scrollbar{width:0;height:0;}\n</style>\n</helmet>\n<div style=\"font-family:'Inter',sans-serif;\">\n  <div style=\"position:fixed;right:28px;bottom:28px;z-index:50;\">\n    <button onClick=\"{{ open }}\" title=\"Задайте вопрос о здоровье или работе портала\" style=\"display:flex;align-items:center;gap:10px;height:54px;padding:0 22px 0 18px;border:none;border-radius:999px;background:linear-gradient(135deg,var(--primary),var(--primary-darker));color:#fff;font-size:15px;font-weight:600;font-family:inherit;cursor:pointer;box-shadow:0 16px 32px -12px rgba(10,13,20,.25);\">\n      <i class=\"ri-sparkling-2-fill\" style=\"font-size:22px;\"></i>AI-помощник\n    </button>\n  </div>\n  <sc-if value=\"{{ isOpen }}\" hint-placeholder-val=\"{{ false }}\">\n    <div onClick=\"{{ close }}\" style=\"position:fixed;inset:0;z-index:60;background:rgba(10,13,20,.5);display:flex;align-items:flex-end;justify-content:flex-end;padding:24px;animation:mp-fade .2s ease;\">\n      <div onClick=\"{{ stop }}\" style=\"width:440px;max-width:100%;height:640px;max-height:90vh;background:#fff;border-radius:20px;box-shadow:0 24px 48px -12px rgba(10,13,20,.3);display:flex;flex-direction:column;overflow:hidden;animation:mp-pop .25s ease;\">\n        <div style=\"padding:18px 20px;border-bottom:1px solid var(--stroke);display:flex;align-items:center;gap:12px;\">\n          <div style=\"width:40px;height:40px;border-radius:11px;background:linear-gradient(135deg,var(--primary),var(--primary-darker));display:flex;align-items:center;justify-content:center;\"><i class=\"ri-sparkling-2-fill\" style=\"color:#fff;font-size:20px;\"></i></div>\n          <div style=\"flex:1;\"><div style=\"font-size:16px;font-weight:600;\">AI-помощник по здоровью</div><div style=\"font-size:12px;color:var(--green);display:flex;align-items:center;gap:5px;\"><span style=\"width:7px;height:7px;border-radius:50%;background:var(--green);\"></span>В сети</div></div>\n          <button onClick=\"{{ close }}\" style=\"width:34px;height:34px;border:none;border-radius:8px;background:var(--n100);cursor:pointer;display:flex;align-items:center;justify-content:center;\"><i class=\"ri-close-line\" style=\"font-size:20px;color:var(--n500);\"></i></button>\n        </div>\n        <div ref=\"{{ chatRef }}\" class=\"mp-scroll\" style=\"flex:1;overflow-y:auto;padding:20px;display:flex;flex-direction:column;gap:14px;background:var(--n100);\">\n          <sc-for list=\"{{ messages }}\" as=\"m\" hint-placeholder-count=\"1\">\n            <div style=\"{{ m.row }}\"><div style=\"{{ m.bubble }}\">{{ m.text }}</div></div>\n          </sc-for>\n          <sc-if value=\"{{ showSuggestions }}\" hint-placeholder-val=\"{{ true }}\">\n            <div style=\"display:flex;flex-direction:column;gap:8px;margin-top:4px;\">\n              <div style=\"font-size:12px;color:var(--n400);font-weight:500;\">Попробуйте спросить:</div>\n              <sc-for list=\"{{ suggestions }}\" as=\"sg\" hint-placeholder-count=\"4\">\n                <button onClick=\"{{ sg.onClick }}\" style=\"text-align:left;background:#fff;border:1px solid var(--stroke);border-radius:12px;padding:11px 14px;font-size:13px;color:var(--n700);font-family:inherit;cursor:pointer;display:flex;align-items:center;gap:8px;\"><i class=\"ri-question-answer-line\" style=\"color:var(--primary);font-size:16px;\"></i>{{ sg.text }}</button>\n              </sc-for>\n            </div>\n          </sc-if>\n        </div>\n        <div style=\"padding:14px 16px;border-top:1px solid var(--stroke);background:#fff;\">\n          <div style=\"display:flex;gap:8px;align-items:flex-end;\">\n            <input value=\"{{ input }}\" onChange=\"{{ onInput }}\" onKeyDown=\"{{ onKey }}\" placeholder=\"Введите вопрос\" style=\"flex:1;height:46px;border:1px solid var(--stroke);border-radius:12px;padding:0 14px;font-size:14px;font-family:inherit;background:var(--n100);outline:none;\" />\n            <button onClick=\"{{ send }}\" style=\"width:46px;height:46px;border:none;border-radius:12px;background:var(--primary);color:#fff;cursor:pointer;display:flex;align-items:center;justify-content:center;flex:0 0 auto;\"><i class=\"ri-send-plane-fill\" style=\"font-size:20px;\"></i></button>\n          </div>\n          <div style=\"font-size:11px;color:var(--n400);margin-top:10px;line-height:1.4;display:flex;gap:6px;\"><i class=\"ri-information-line\" style=\"font-size:14px;flex:0 0 auto;margin-top:1px;\"></i>Информация носит справочный характер и не заменяет консультацию медицинского работника.</div>\n        </div>\n      </div>\n    </div>\n  </sc-if>\n</div>\n","j":"\nclass Component extends DCLogic {\n  constructor(props){\n    super(props);\n    this.chatRef = React.createRef();\n    this.state = { open:false, input:'', messages:[{ role:'bot', text:'Здравствуйте! Я помогу с вопросами о здоровье и работе портала. Опишите симптом или задайте вопрос — я подскажу, что делать и куда обратиться.' }] };\n  }\n  componentDidUpdate(){ if(this.chatRef.current) this.chatRef.current.scrollTop = this.chatRef.current.scrollHeight; }\n  botReply(q){\n    const t = q.toLowerCase();\n    if(/(голов|мигрен)/.test(t)) return 'Головная боль может быть вызвана переутомлением, повышенным давлением, обезвоживанием или простудой.\\n\\nРекомендации: отдохните, выпейте воды, измерьте давление. Если боль резкая, сопровождается нарушением зрения или речи — обратитесь за помощью незамедлительно.\\n\\nРекомендуемый специалист: терапевт, при повторяющихся болях — невролог.\\nРаздел портала: «Каталог медицинских услуг» → запись на приём.';\n    if(/(температ|жар|39|38|лихорад)/.test(t)) return 'Высокая температура — признак воспалительного процесса или инфекции.\\n\\nРекомендации: обильное питьё, покой, жаропонижающее при температуре выше 38,5 °C. Если держится более 3 дней или выше 39,5 °C — вызовите врача на дом.\\n\\nРекомендуемый специалист: терапевт (для детей — педиатр).\\nСервис: «Вызов врача на дом» в каталоге услуг.';\n    if(/(груд|сердц|инфаркт)/.test(t)) return '⚠ Боль в груди может быть признаком сердечного состояния и требует внимания.\\n\\nЕсли боль сильная, отдаёт в руку или челюсть, есть одышка и холодный пот — немедленно вызывайте скорую по номеру 103.\\n\\nВ плановом порядке — консультация кардиолога.\\nРаздел: «Экстренная помощь» → Инфаркт.';\n    if(/(мрт|осмс|кт|узи|бесплатн|направлени)/.test(t)) return 'Чтобы получить МРТ по ОСМС, нужно: 1) быть застрахованным в системе ОСМС; 2) получить направление от лечащего врача; 3) выбрать медорганизацию из каталога.\\n\\nПроверить статус страхования: сервис «Проверка ОСМС».\\nНайти услугу и медорганизации: «Каталог медицинских услуг» → МРТ.';\n    if(/(поликлиник|ближайш|организац|больниц|где наход|адрес)/.test(t)) return 'Найти ближайшую медицинскую организацию можно в сервисе «Медицинские организации» — там есть поиск по региону и интерактивная карта с метками поликлиник, стационаров, аптек и лабораторий.\\n\\nДля прикрепления к поликлинике потребуется авторизация в личном кабинете пациента.';\n    if(/(лекарств|таблетк|препарат|аналог|аптек)/.test(t)) return 'Информацию о препарате — инструкцию, показания, противопоказания и аналоги — можно найти в сервисе «Лекарства».\\n\\nТам же есть проверка наличия препарата в аптеках по региону.\\nВажно: подбор и замену препаратов должен назначать врач.';\n    return 'Спасибо за вопрос. Я могу подсказать по симптомам, записи к врачу, статусу ОСМС, лекарствам и поиску медорганизаций.\\n\\nУточните, пожалуйста, ваш запрос — например, опишите симптом или назовите услугу, которая вас интересует.';\n  }\n  send(text){\n    const q = (text != null ? text : this.state.input).trim();\n    if(!q) return;\n    const reply = this.botReply(q);\n    this.setState(s => ({ messages:[...s.messages, { role:'user', text:q }, { role:'bot', text:reply }], input:'' }));\n  }\n  renderVals(){\n    const s = this.state;\n    const messages = s.messages.map(m => ({\n      text:m.text,\n      row:`display:flex;${m.role==='user'?'justify-content:flex-end;':'justify-content:flex-start;'}`,\n      bubble:m.role==='user'\n        ?'max-width:80%;background:#4D42E9;color:#fff;border-radius:16px 16px 4px 16px;padding:12px 14px;font-size:14px;line-height:1.5;white-space:pre-line;'\n        :'max-width:88%;background:#fff;color:#0A0D14;border:1px solid #E2E4E9;border-radius:16px 16px 16px 4px;padding:12px 14px;font-size:14px;line-height:1.55;white-space:pre-line;box-shadow:0 1px 2px rgba(10,13,20,.03);',\n    }));\n    const suggestions = ['У меня болит голова','Температура 39 градусов','К какому врачу при боли в груди','Как получить МРТ по ОСМС','Где находится ближайшая поликлиника']\n      .map(text => ({ text, onClick: () => this.send(text) }));\n    return {\n      isOpen:s.open, open:()=>this.setState({open:true}), close:()=>this.setState({open:false}), stop:(e)=>e.stopPropagation(),\n      messages, showSuggestions:s.messages.length<=1, suggestions, chatRef:this.chatRef,\n      input:s.input, onInput:(e)=>this.setState({input:e.target.value}), onKey:(e)=>{ if(e.key==='Enter') this.send(); }, send:()=>this.send(),\n    };\n  }\n}\n"}};
(function(){function r(){if(!window.__dcUpdate){return setTimeout(r,0);}Object.keys(__DC_CHILDREN).forEach(function(n){try{window.__dcUpdate(n,"html",__DC_CHILDREN[n].h,false);if(__DC_CHILDREN[n].j)window.__dcUpdate(n,"js",__DC_CHILDREN[n].j,false);if(window.__dcRegistry&&window.__dcRegistry[n])window.__dcRegistry[n].fetched=true;}catch(e){}});}r();})();